  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest analogue, NA-014, contains a piperazine amide and aryl nitrile similar to the query and showed a brain-to-plasma ratio of 1.32 in mice, supporting meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Compound 21, which contains the same cyanopyrazole motif as the query, maintained a brain-to-plasma ratio greater than 1 in rats and mice, directly supporting CNS penetration of the cyanopyrazole-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "ASN90, a piperazine amide heteroaromatic analogue, showed a brain/plasma ratio of about 1 with passive diffusion across the BBB in rats, indicating that this structural class can achieve adequate brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A non-penetrant analogue, compound 10e, contains an additional basic secondary amine and multiple amide H-bond donors not present in the query, so its failure to penetrate the brain is less transferable to the query's more compact, lipophilic structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query's compact lipophilic piperazine-acyl-cyanopyrazole structure aligns with multiple direct CNS-penetrant analogues showing B/P around 1 or higher, CSF exposure, or passive diffusion, while the few non-penetrant analogues carry additional polar/ionizable liabilities absent in the query.",
  "evidence_gaps": [
    "No direct BBB/PK measurement for the exact query molecule.",
    "Morgan similarities to evidence molecules are low, limiting structural transferability.",
    "Efflux transporter liability and unbound brain concentrations were not directly assessed.",
    "No human CNS exposure data are available for the query or close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

